def contains_match(output, expected):
    return 1.0 if expected.lower() in output.lower() else 0.0


def run_eval(dataset, task_fn, scorer_fn):
    if not dataset:
        return 0.0
    scores = [scorer_fn(task_fn(item["input"]), item["expected"]) for item in dataset]
    return sum(scores) / len(scores)


dataset = [
    {"input": "capital of France", "expected": "Paris"},
    {"input": "capital of Japan", "expected": "Tokyo"},
    {"input": "capital of Italy", "expected": "Rome"},
    {"input": "capital of Spain", "expected": "Madrid"},
    {"input": "capital of Germany", "expected": "Berlin"},
]

answers = {
    "capital of France": "The capital is paris.",
    "capital of Japan": "It is Tokyo.",
    "capital of Italy": "Rome, of course.",
    "capital of Spain": "Madrid is the capital.",
    "capital of Germany": "I think it's Munich.",
}


def task_fn(prompt):
    return answers[prompt]


print(run_eval(dataset, task_fn, contains_match))
